		rcu_read_unlock();
 return ret;
 }
	get_task_struct(tsk);
	rcu_read_unlock();

	ret = do_prlimit(tsk, resource, new_rlim ? &new : NULL,
			old_rlim ? &old : NULL);

 if (!ret && old_rlim) {
		rlim_to_rlim64(&old, &old64);
 if (copy_to_user(old_rlim, &old64, sizeof(old64)))
			ret = -EFAULT;
 }

	put_task_struct(tsk);
 return ret;
}


